const items = $input.all().map(item => {
  let body = item.json.body;

  // 🧹 Step 1: Parse body if it’s a JSON string
  try {
    if (typeof body === 'string') body = JSON.parse(body);
  } catch (err) {}

  // 🧩 Step 2: Handle if body itself is an array (e.g., Recipe format)
  if (Array.isArray(body)) {
    const isDispatch = body.every(entry =>
      entry.item && entry.quantity !== undefined && entry.unit
    );

    const isRecipe = body.every(entry =>
      entry.menuItem && (entry.ingredient || entry.ingredients)
    );

    if (isDispatch) {
      return body.map(entry => ({
        type: 'Dispatch',
        mode: 'Dispatch Items',
        location: 'N/A',
        item: entry.item || 'N/A',
        quantity: entry.quantity || 0,
        unit: entry.unit || 'N/A',
        price: '0', // ✅ string
        date: new Date().toISOString().split('T')[0],
        supplier: 'N/A',
        branch: 'Null',
        invoiceNumber: 'N/A',
      }));
    }

    if (isRecipe) {
      return body.map(entry => ({
        type: 'Recipe',
        menuItem: entry.menuItem || 'N/A',
        ingredient: entry.ingredient || 'N/A',
        quantityUsed: entry.quantityUsed || 0,
        unit: entry.unit || 'N/A',
        timestamp: entry.timestamp || new Date().toISOString(),
      }));
    }

    return body.map(entry => ({
      type: 'Unknown Array Format',
      raw: entry,
    }));
  }

  // 🧩 Step 2.5: Handle Dispatch Items nested inside "body.items"
  if (body.items && Array.isArray(body.items) && body.mode === 'Dispatch Items') {
    return body.items.map(entry => ({
      type: 'Dispatch',
      mode: body.mode || 'Dispatch Items',
      location: body.location || 'N/A',
      item: entry.item || 'N/A',
      quantity: entry.quantity || 0,
      unit: entry.unit || 'N/A',
      price: '0', // ✅ string
      date: body.date || new Date().toISOString().split('T')[0],
      supplier: body.supplier || 'N/A',
      branch: body.branch || 'Null',
      invoiceNumber: body.invoiceNumber || 'N/A',
    }));
  }

  // 🧩 Step 3: Handle Recipe container (menuItem + ingredients)
  if (body.ingredients && Array.isArray(body.ingredients)) {
    return body.ingredients.map(entry => ({
      Type: 'Recipe',
      menuItem: body.menuItem || entry.menuItem || 'N/A',
      ingredient: entry.ingredient || 'N/A',
      quantityUsed: entry.quantityUsed || 0,
      unit: entry.unit || 'N/A',
      timestamp: body.timestamp || new Date().toISOString(),
    }));
  }

  // 🧩 Step 4: Handle Inventory / Add Items
  let formattedDate;
  if (body.date) {
    const cleanDate = body.date.replace(/(st|nd|rd|th)/, '');
    try {
      const parsedDate = new Date(cleanDate);
      formattedDate = isNaN(parsedDate)
        ? new Date().toISOString().split('T')[0]
        : parsedDate.toISOString().split('T')[0];
    } catch {
      formattedDate = new Date().toISOString().split('T')[0];
    }
  } else {
    formattedDate = new Date().toISOString().split('T')[0];
  }

  let quantityValue = 0;
  let unitValue = 'N/A';
  if (body.quantity) {
    const quantityMatch = body.quantity.trim().match(/(\d+)\s*([a-zA-Z]+)/);
    if (quantityMatch) {
      quantityValue = parseInt(quantityMatch[1], 10) || 0;
      unitValue = quantityMatch[2] || 'N/A';
    } else {
      quantityValue = parseInt(body.quantity.trim(), 10) || 0;
    }
  }

  // 🧩 Step 4.5: Handle Price (always convert to string)
  let priceValue = '0';
  if (body.price !== undefined && body.price !== null) {
    const numericPrice = parseFloat(String(body.price).replace('PKR', '').trim()) || 0;
    priceValue = numericPrice.toString(); // ✅ convert to string
  }

  return {
    type: 'Inventory',
    mode: body.mode || 'N/A',
    location: body.location || 'N/A',
    item: body.item || 'N/A',
    quantity: quantityValue,
    price: priceValue, // ✅ now always a string
    date: formattedDate,
    supplier: body.supplier || 'N/A',
    branch: body.branch || 'Null',
    unit: unitValue,
    invoiceNumber: body.invoiceNumber || 'N/A',
  };
});

// 🧹 Step 5: Flatten any nested arrays
return items.flat();

// Get merged sheet data
const rows = items.map(item => item.json);

// 1️⃣ Get all dispatch rows
const dispatchedItems = rows.filter(r => r.mode === "Dispatch Items");

// 2️⃣ Prepare output and a map to sum quantities
const output = [];
const dispatchTotals = {};
const processedMenuItems = new Set();

// 3️⃣ Sum dispatch quantities for each menu item
for (const dispatch of dispatchedItems) {
  const menuItem = (dispatch.item || dispatch.menuItem || "").trim();
  const qty = Number(dispatch.quantity) || 0;

  if (!dispatchTotals[menuItem]) {
    dispatchTotals[menuItem] = 0;
  }
  dispatchTotals[menuItem] += qty;
}

// 4️⃣ Loop over each menu item with total dispatch quantity
for (const [menuItem, totalDispatchedQty] of Object.entries(dispatchTotals)) {
  const recipeRows = rows.filter(
    r => (r.menuItem || "").toLowerCase() === (menuItem || "").toLowerCase()
  );

  // 5️⃣ Build ingredient list
  const uniqueIngredients = [];
  const seen = new Set();

  for (const r of recipeRows) {
    const key = `${r.ingredient}-${r.unit}-${r.quantityUsed}`;
    if (!seen.has(key)) {
      seen.add(key);

      const baseQty = Number(r.quantityUsed) || 0;
      uniqueIngredients.push({
        ingredient: r.ingredient,
        unit: r.unit,
        baseQuantity: baseQty,
        totalQuantity: baseQty * totalDispatchedQty
      });
    }
  }

  // 6️⃣ Push combined data
  output.push({
    json: {
      menuItem,
      dispatchedQuantity: totalDispatchedQty,
      ingredients: uniqueIngredients
    }
  });
}

return output;

// ✅ Combine all inputs into a single array of JSON objects
const data = items.map(item => item.json);

// ✅ Extract data groups
const inventoryItems = data.filter(d => d.type === "Inventory" && d.mode === "Add Items");
const dispatchItems = data.filter(d => d.type === "Dispatch" && d.mode === "Dispatch Items");
const recipes = data.filter(d => d.menuItem); // all recipes

// ✅ Define conversion map (to grams or milliliters)
const unitConversion = {
  g: 1,
  kg: 1000,
  ml: 1,
  l: 1000
};

// ✅ Clone inventory so we don't mutate original
let updatedInventory = JSON.parse(JSON.stringify(inventoryItems));

// ✅ Helper function: Deduct quantity from inventory (FIFO)
function deductFromInventory(itemName, deductQty, unit) {
  const matches = updatedInventory.filter(
    i => i.item.toLowerCase() === itemName.toLowerCase()
  );
  if (!matches.length) return; // item not found

  const dispatchFactor = unitConversion[unit.toLowerCase()] || 1;
  let remainingToDeduct = deductQty * dispatchFactor;

  for (const invItem of matches) {
    if (remainingToDeduct <= 0) break;

    const invUnit = invItem.unit.toLowerCase();
    const invFactor = unitConversion[invUnit] || 1;
    const invQtyInBase = invItem.quantity * invFactor;

    if (invQtyInBase >= remainingToDeduct) {
      invItem.quantity = (invQtyInBase - remainingToDeduct) / invFactor;
      remainingToDeduct = 0;
    } else {
      invItem.quantity = 0;
      remainingToDeduct -= invQtyInBase;
    }
  }
}

// ✅ Process each dispatch item
for (const dispatch of dispatchItems) {
  const dishName = dispatch.item;
  const dishQty = dispatch.quantity;
  const dishUnit = (dispatch.unit || "").toLowerCase();

  // Find recipe
  const recipe = recipes.find(r => r.menuItem === dishName);

  if (recipe && recipe.ingredients?.length) {
    // Deduct ingredients based on recipe
    for (const ingredient of recipe.ingredients) {
      const ingredientName = ingredient.ingredient;
      const ingredientQty = ingredient.baseQuantity * dishQty; // total used
      const ingredientUnit = ingredient.unit;

      deductFromInventory(ingredientName, ingredientQty, ingredientUnit);
    }
  } else {
    // No recipe, deduct the item itself
    deductFromInventory(dishName, dishQty, dishUnit);
  }
}

// ✅ Return updated inventory
return updatedInventory.map(item => ({ json: item }));

// Get all input items
const data = items.map(item => item.json);

// Filter only rows where mode = "Dispatch Items" (case-insensitive)
const dispatchItems = data.filter(entry =>
  entry.mode && entry.mode.toLowerCase().trim() === "dispatch items"
);

// If no Dispatch Items found, return a message instead
if (dispatchItems.length === 0) {
  return [
    {
      json: {
        message: "⚠️ No dispatch items found in the input data.",
      },
    },
  ];
}

// Otherwise, return all dispatch rows as JSON
return dispatchItems.map(entry => ({
  json: entry,
}));
